span.t-att-class:
{
                    'badge mt-1': true,
                    'bg-warning font-color-black-fixed': props.address.status === 'pending',
                    'bg-success font-color-white-fixed': props.address.status === 'visited',
                    'bg-danger font-color-white-fixed': props.address.status === 'skipped',
                }

div.t-att-class:
{
                            'bg-secondary font-color-black-fixed': progressPercent === 25,
                            'bg-info font-color-white-fixed': progressPercent === 50,
                            'bg-primary font-color-white-fixed': progressPercent === 75,
                            'bg-success font-color-white-fixed': progressPercent === 100,
                        }
